package io.mavsdk.kotlin.plugins.tune

import io.mavsdk.kotlin.System
import kotlinx.coroutines.suspendCancellableCoroutine
import kotlin.coroutines.resume
import kotlin.coroutines.resumeWithException


class Tune internal constructor(private val handle: Long) : AutoCloseable {

    enum class Result(val value: Int) {
        UNKNOWN(0),
        SUCCESS(1),
        INVALID_TEMPO(2),
        TUNE_TOO_LONG(3),
        ERROR(4),
        NO_SYSTEM(5),
        ;
        companion object {
            fun fromValue(v: Int): Result = entries.find { it.value == v } ?: values()[0]
        }
    }

    enum class SongElement(val value: Int) {
        STYLE_LEGATO(0),
        STYLE_NORMAL(1),
        STYLE_STACCATO(2),
        DURATION_1(3),
        DURATION_2(4),
        DURATION_4(5),
        DURATION_8(6),
        DURATION_16(7),
        DURATION_32(8),
        NOTE_A(9),
        NOTE_B(10),
        NOTE_C(11),
        NOTE_D(12),
        NOTE_E(13),
        NOTE_F(14),
        NOTE_G(15),
        NOTE_PAUSE(16),
        SHARP(17),
        FLAT(18),
        OCTAVE_UP(19),
        OCTAVE_DOWN(20),
        ;
        companion object {
            fun fromValue(v: Int): SongElement = entries.find { it.value == v } ?: values()[0]
        }
    }

    data class TuneDescription(
        // TODO: repeated primitive field songElements
        val tempo: Int,
    )

    fun playTune(tuneDescription: TuneDescription): Result =
        Result.fromValue(playTuneBlocking(tuneDescription))

    suspend fun playTuneAsync(tuneDescription: TuneDescription): Result = suspendCancellableCoroutine { continuation ->
        val callback = PlayTuneCallback { result ->
            val r = Result.fromValue(result)
            if (r == Result.SUCCESS) {
                continuation.resume(r)
            } else {
                continuation.resumeWithException(
                    TuneException(r, "playTune failed: ${r.name}")
                )
            }
        }
        playTuneAsyncNative(tuneDescription, callback)
    }

    private fun interface PlayTuneCallback { fun invoke(result: Int) }

    private external fun playTuneBlocking(tuneDescription: TuneDescription): Int
    private external fun playTuneAsyncNative(tuneDescription: TuneDescription, callback: PlayTuneCallback)
    private external fun destroy()

    override fun close() {
        destroy()
    }

    class TuneException(
        val result: Result,
        message: String
    ) : Exception(message)

    companion object {
        fun create(system: System): Tune {
            val handle = createNative(system.getHandle())
            return Tune(handle)
        }
        private external fun createNative(systemHandle: Long): Long
    }
}